import re

from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase


class TrfInternalDispFailure(Exception):
    """
    Exception class for ue_stats
    """
    pass


class TrfInternalDisp(EgateCommandBase):
    """
    Parser for trf_internal_disp command output.
    """

    # class naming convention for future extensions:
    # x = @classmethod contructor name
    # __created_with__ = x
    # parse_x  --> parsing method name
    # output_x --> pyparsing parser name

    def __init__(self, rat='4G', **params):
        """

        :param params:
        """
        super(TrfInternalDisp, self).__init__()
        self.command = 'trf_internal_disp'
        self.params = params
        self.to_execute = self.command
        self.executed_phrase = r'.*?Parameters of internal traffic.*?EGATE>'
        self.rat = rat
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def _build_command(self):
        """
        Build bearer_disp command.

        :return: None
        """
        for param, value in list(self.params.items()):
            self.to_execute += ' {}={}'.format(param, value)

    def execute_and_parse(self, egate_id=0):
        """
        Execute egate cmd and parse its output.
        :return: parsed output
        """
        status, output = super(TrfInternalDisp, self).execute(egate_id=egate_id, command=self.to_execute)
        if status:
            parsed_output = self._parse_trf_internal_disp_output(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output
        else:
            raise TrfInternalDispFailure(output)

    def _parse_trf_internal_disp_output(self, output):
        """

        :param output:
        :return:
        """
        if self.rat == '4G':
            if 'pdu' in list(self.params.keys()):
                logger.debug('PDU can not be specified for 4G UE.')
                return {}
            else:
                return self._parse_4g_ue(output)
        if self.rat == '5G':
            if 'pdu' in list(self.params.keys()):
                return self._parse_5g_ue(output)
            else:
                logger.debug('PDU must be specified for 5G UE.')
                return {}

    def _parse_4g_ue(self, cmd_output):
        """

        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()

        current_bearer = ''
        current_trf_id = ''
        current_direction = ''
        trf_internal_info = {}

        for line in output[1:]:
            bearer_id_line = re.search(r'Bearer #(\d+)', ''.join(line))
            if bearer_id_line:
                current_trf_id = ''
                current_direction = ''
                bearer_id = bearer_id_line.group(1)
                current_bearer = bearer_id
                trf_internal_info[current_bearer] = {}
                continue

            trf_id_line = re.search(r'trf_id \= (\d+)', ''.join(line))
            if trf_id_line:
                current_direction = ''
                trf_id = trf_id_line.group(1)
                current_trf_id = trf_id
                if trf_id not in list(trf_internal_info[current_bearer].keys()):
                    trf_internal_info[current_bearer][current_trf_id] = {}
                continue

            if 'direction' in line[0]:
                current_direction = line[1]
                trf_internal_info[current_bearer][current_trf_id][current_direction] = {}
                continue

            if current_trf_id and current_direction:
                trf_internal_info[current_bearer][current_trf_id][current_direction][line[0]] = line[1]

        return trf_internal_info

    def _parse_5g_ue(self, cmd_output):
        """

        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output, findall=True)
        output = cmd_parser.get_list_of_output_parsed_lines()

        current_qfi = ''
        current_trf_id = ''
        current_direction = ''
        trf_internal_info = {}

        for line in output[1:]:
            qfi_id_line = re.search(r'pdu # \d+ qfi # (\d+)', ''.join(line))
            if qfi_id_line:
                current_trf_id = ''
                current_direction = ''
                qfi_id = qfi_id_line.group(1)
                current_qfi = qfi_id
                if current_qfi not in list(trf_internal_info.keys()):
                    trf_internal_info[current_qfi] = {}
                continue

            trf_id_line = re.search(r'trf_id # (\d+)', ''.join(line))
            if trf_id_line:
                current_direction = ''
                trf_id = trf_id_line.group(1)
                current_trf_id = trf_id
                if current_trf_id not in list(trf_internal_info[current_qfi].keys()):
                    trf_internal_info[current_qfi][current_trf_id] = {}
                continue

            if 'direction' in line[0]:
                current_direction = line[1]
                trf_internal_info[current_qfi][current_trf_id][current_direction] = {}
                continue

            if 'traffic information' in ''.join(line):
                continue

            if current_trf_id and current_direction:
                trf_internal_info[current_qfi][current_trf_id][current_direction][line[0]] = line[1]

        return trf_internal_info
